import{_ as h,C as s,o as c,c as d,j as t,a,E as o,a8 as p}from"./chunks/framework.27XeWUA0.js";const n="/schedule-dashboard/thumbs/yt/-NFMsM2y0Vk-640.webp",u="/schedule-dashboard/thumbs/yt/-NFMsM2y0Vk-1280.webp",r="/schedule-dashboard/thumbs/yt/ubK6Q53jKg8-640.webp",w="/schedule-dashboard/thumbs/yt/ubK6Q53jKg8-1280.webp",K=JSON.parse('{"title":"AI Digest · Tue 24 Nov 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-11-24","routine":"digest"},"relativePath":"digest/2026-11-24.md","filePath":"digest/[date].md"}'),g={name:"digest/2026-11-24.md"},m=n+" 640w, "+u+" 1280w",b=r+" 640w, "+w+" 1280w",y={id:"ai-digest-·-tue-24-nov-2026",tabindex:"-1"};function f(v,e,k,M,_,S){const i=s("Badge"),l=s("DayFilter");return c(),d("div",null,[t("h1",y,[e[0]||(e[0]=a("AI Digest · Tue 24 Nov 2026 ",-1)),o(i,{type:"tip",text:"2"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-tue-24-nov-2026","aria-label":'Permalink to "AI Digest · Tue 24 Nov 2026 <Badge type="tip" text="2" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 24 Nov 2026 · run date Tue 24 Nov 2026 · 2 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(" There is 1 new talk (24 Nov, 1:30 AM IST): Dex Horthy (HumanLayer, now part of Factory) with 12 rules for a software factory that doesn't ship slop, 20 minutes. The factory framing is heavily repeated ground, but his new SlopCodeBench findings and the Anti-Slop Manifesto launch are fresh, so skim from 7:00.")]),t("p",null,[t("strong",null,"Better Stack:"),a(" There is 1 new video (24 Nov, 12:30 AM IST), and it's fresh ground: a hands-on test of Shadcn's UI SDK, which lets agents both build accessible UI and operate a page directly. Agents read about 5× less of the page, and the approval gate stopped a risky click. Worth watching.")])],-1)),o(l),e[5]||(e[5]=p('<div class="grid cards2"><article class="it full" id="v--NFMsM2y0Vk" data-title="12 Rules for a Software Factory That Doesn&#39;t Ship Slop — Dex Horthy, Factory" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=-NFMsM2y0Vk" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+m+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=-NFMsM2y0Vk" target="_blank" rel="noopener">12 Rules for a Software Factory That Doesn&#39;t Ship Slop — Dex Horthy, Factory</a></h3><div class="meta">AI Engineer · Dex Horthy, Factory (formerly CEO of HumanLayer) · uploaded 24 Nov, 1:30 AM IST · 20:24</div><div class="verdict v-skim"><b>Verdict:</b> skim from 7:00 — the opening is well-worn factory material, but the SlopCodeBench findings and the manifesto are new.</div><div class="repeat">🔁 Repeat: &#39;software factory&#39; — seen 28 times before. New here: the claim that a software factory is mostly decades-old engineering practice with an agent in the build step, organised as 12 practices.</div><div class="repeat">🔁 Repeat: &#39;human-in-the-loop review&#39; — seen 53 times before. New here: the launch of the Anti-Slop Manifesto (slopmanifesto.com), which argues there will always be value in reviewing something, whether that&#39;s code, a plan or the result.</div><div class="repeat">🔁 Repeat: &#39;AI-generated code validation&#39; — seen 44 times before. New here: new SlopCodeBench data showing that newer models write more slop patterns than models from six months ago.</div><div class="sh">Factories are just good engineering</div><ul><li><strong>Fresh data behind &quot;read the code&quot;:</strong> SlopCodeBench, from Gabe Orlanski&#39;s lab at the University of Wisconsin, is far from solved: GPT-5.5 scores 15% and Astra about 16.3%. He also cites a Pharos study finding that 30% of PRs now merge without review, with more incidents per PR and more bugs per developer. HumanLayer became part of Factory about a week before the talk (<a href="https://www.youtube.com/watch?v=-NFMsM2y0Vk&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=-NFMsM2y0Vk&amp;t=120s" target="_blank" rel="noopener">2:00</a>)</li><li><strong>Same pipeline, agent in the build step:</strong> A pre-AI factory already had a tracker, tests, PRs, CI and linters, canaries and feature flags, plus monitoring that pages someone at 3 AM. Making it agentic mostly means an agent does the build step (<a href="https://www.youtube.com/watch?v=-NFMsM2y0Vk&amp;t=120s" target="_blank" rel="noopener">2:00</a>–<a href="https://www.youtube.com/watch?v=-NFMsM2y0Vk&amp;t=300s" target="_blank" rel="noopener">5:00</a>) (repeat)</li><li><strong>Forward and back pressure:</strong> Forward pressure decides what starts work automatically, such as sending feature requests and incidents straight to the factory so a 3 AM page arrives with a candidate PR. Back pressure covers agent code review, agent testing, strong CI and linters, even Lean-style formal checks, so agents can improve the result before a human looks (<a href="https://www.youtube.com/watch?v=-NFMsM2y0Vk&amp;t=240s" target="_blank" rel="noopener">4:00</a>–<a href="https://www.youtube.com/watch?v=-NFMsM2y0Vk&amp;t=420s" target="_blank" rel="noopener">7:00</a>)</li></ul><div class="sh">Know your enemy: slop compounds</div><ul><li><strong>The benchmark tests evolving a codebase:</strong> Models can clone Excel or Redis when the whole spec is known up front, but SlopCodeBench gives the work in checkpoints, the way features really ship. It scores code quality with cyclomatic complexity, lines per symbol and about 200 rules, many written after comparing model code with pre-AI repos (<a href="https://www.youtube.com/watch?v=-NFMsM2y0Vk&amp;t=420s" target="_blank" rel="noopener">7:00</a>–<a href="https://www.youtube.com/watch?v=-NFMsM2y0Vk&amp;t=480s" target="_blank" rel="noopener">8:00</a>)</li><li><strong>Newer models write more slop:</strong> Bad patterns appear more often in today&#39;s models than in models from six months ago. Models learned to raise exceptions instead of returning tuples, and Claude and GLM now write Python 3 like Python 2, using %s format strings instead of f-strings. Anthropic says telling Fable it owns the codebase keeps it clean, but his team hasn&#39;t finished testing that (<a href="https://www.youtube.com/watch?v=-NFMsM2y0Vk&amp;t=480s" target="_blank" rel="noopener">8:00</a>–<a href="https://www.youtube.com/watch?v=-NFMsM2y0Vk&amp;t=560s" target="_blank" rel="noopener">9:20</a>)</li><li><strong>Plan by &quot;expected pain&quot;:</strong> Weigh the chance something has to change later against how hard it would be to change. A two-sentence prompt has maybe a 50% chance of needing a few more prompts, and a five-hour spec maybe a 10% chance of rework. He doesn&#39;t argue about button colours, but he gets database schemas right before building (<a href="https://www.youtube.com/watch?v=-NFMsM2y0Vk&amp;t=540s" target="_blank" rel="noopener">9:00</a>–<a href="https://www.youtube.com/watch?v=-NFMsM2y0Vk&amp;t=660s" target="_blank" rel="noopener">11:00</a>)</li></ul><div class="sh">Practical tools</div><ul><li><strong>Visual alignment and anti-slop rules:</strong> His &quot;Show Me&quot; skill (about 40,000 installs) has agents answer with HTML mockups, tables and charts instead of walls of text. For TypeScript he points to Cloudflare engineer Dylan Moroy&#39;s Anti Slop repo (about 100 rules) and Factory&#39;s ESLint plugin. Let agents check their own work with screenshots, browsers, videos or curl (<a href="https://www.youtube.com/watch?v=-NFMsM2y0Vk&amp;t=660s" target="_blank" rel="noopener">11:00</a>–<a href="https://www.youtube.com/watch?v=-NFMsM2y0Vk&amp;t=720s" target="_blank" rel="noopener">12:00</a>)</li><li><strong>Slop has its place:</strong> Prototypes and anything behind a feature flag are fine as slop. Give models a feature-flag system (PostHog, Statsig, LaunchDarkly) so they can test what works. Also bring designs and decisions from Notion and Google Docs next to the code. You can buy VMs, harnesses and control planes, but nobody can sell you verification of your own code (<a href="https://www.youtube.com/watch?v=-NFMsM2y0Vk&amp;t=720s" target="_blank" rel="noopener">12:00</a>–<a href="https://www.youtube.com/watch?v=-NFMsM2y0Vk&amp;t=900s" target="_blank" rel="noopener">15:00</a>)</li></ul><div class="sh">The Anti-Slop Manifesto</div><ul><li><strong>What it says:</strong> Written with Swyx, Philipp and other conference speakers, it values outcomes over outputs, understanding over speed, and your own thinking over the model&#39;s first draft. It defines slop as putting in less effort to produce something than you ask the reader to spend understanding it. Producing a 1,000-line PR costs almost nothing, but reviewing it still costs the same, and slop compounds as the next agent copies it (<a href="https://www.youtube.com/watch?v=-NFMsM2y0Vk&amp;t=840s" target="_blank" rel="noopener">14:00</a>–<a href="https://www.youtube.com/watch?v=-NFMsM2y0Vk&amp;t=1020s" target="_blank" rel="noopener">17:00</a>)</li><li><strong>Commitments:</strong> Say when an agent wrote something you send, check it first, and push back kindly when someone sends you slop. Agent reviewers and linters help but aren&#39;t enough, so always review some outputs, how many depending on the stakes. Judge by what shipped and who it helps, not by PRs merged or agents running in parallel. Sign at slopmanifesto.com (<a href="https://www.youtube.com/watch?v=-NFMsM2y0Vk&amp;t=1020s" target="_blank" rel="noopener">17:00</a>–<a href="https://www.youtube.com/watch?v=-NFMsM2y0Vk&amp;t=1224s" target="_blank" rel="noopener">20:24</a>)</li></ul></div></article><article class="it full" id="v-ubK6Q53jKg8" data-title="Shadcn Just Rebuilt UI for AI Agents (UI SDK)" data-channel="Better Stack" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=ubK6Q53jKg8" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+b+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=ubK6Q53jKg8" target="_blank" rel="noopener">Shadcn Just Rebuilt UI for AI Agents (UI SDK)</a></h3><div class="meta">Better Stack · Better Stack · uploaded 24 Nov, 12:30 AM IST · 9:01</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — a short, concrete test of a genuinely new idea: pages built for agents to operate, with real token numbers and an approval-gate demo.</div><div class="repeat">🔁 Repeat: &#39;browser agents&#39; — seen 9 times before. New here: a page that describes its own components to agents (snapshot/query/act) instead of browser agents reading the whole accessibility tree, plus a confirmation step that blocked a risky click.</div><div class="repeat">🔁 Repeat: &#39;agent skills&#39; — seen 33 times before. New here: a UI-behaviors skill that got keyboard focus and tests right on the first try.</div><div class="repeat">🔁 Repeat: &#39;JS/TS ecosystem&#39; — seen 17 times before. New here: Shadcn&#39;s UI SDK, a layer of tested UI behaviours that sits underneath component libraries.</div><div class="sh">What UI SDK is</div><ul><li><strong>The layer under a component library:</strong> Released 12 November, UI SDK splits widgets into 50+ tested behaviours. For example, a select dropdown becomes popup, list selection and typeahead, and roving focus lets arrow keys move through a list on one tab stop. It&#39;s one plain TypeScript package with adapters for React, Vue, Svelte, Solid and Web Components, plus a skill and a testing kit so your agent writes the code (<a href="https://www.youtube.com/watch?v=ubK6Q53jKg8&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=ubK6Q53jKg8&amp;t=90s" target="_blank" rel="noopener">1:30</a>)</li></ul><div class="sh">Agents as builders</div><ul><li><strong>F1 track map in one shot:</strong> With the skill, Claude built a clickable Brazil GP corner map from four behaviours in about 200 lines. Its keyboard and focus tests passed first time, and it scored 100 for accessibility in Lighthouse. Without UI SDK, the same model made the map 15 separate tab stops, with no typeahead and no tests. The design still looked generic and AI-made (<a href="https://www.youtube.com/watch?v=ubK6Q53jKg8&amp;t=90s" target="_blank" rel="noopener">1:30</a>–<a href="https://www.youtube.com/watch?v=ubK6Q53jKg8&amp;t=180s" target="_blank" rel="noopener">3:00</a>)</li></ul><div class="sh">Agents as users</div><ul><li><strong>Bridge instead of accessibility tree:</strong> One line, createAgent, gives your agent three tools: snapshot, query and act. The opening snapshot shrank from about 12 KB to 5 KB, his custom map showed up as an actionable component, and one act call could chain several steps. Asking for &quot;Lando Norris&quot; was refused (it needed the code NOR), but the error listed the valid options. It can also register tools through WebMCP (<a href="https://www.youtube.com/watch?v=ubK6Q53jKg8&amp;t=180s" target="_blank" rel="noopener">3:00</a>–<a href="https://www.youtube.com/watch?v=ubK6Q53jKg8&amp;t=270s" target="_blank" rel="noopener">4:30</a>)</li><li><strong>Benchmarks:</strong> In Vercel&#39;s benchmark (Sonnet in Claude Code, settings screen with 24 members), browser tools took 17 calls, about 292K tokens, 53 s and $0.14. The bridge took 7 calls, about 70K tokens, 31 s and about $0.04, which is 54–68% cheaper across React, Vue and Svelte. In his own test, agents read about 5× less of the page (13 KB vs 63 KB), but time was about equal (27 vs 28 s) and total tokens fell only about 8% (<a href="https://www.youtube.com/watch?v=ubK6Q53jKg8&amp;t=270s" target="_blank" rel="noopener">4:30</a>–<a href="https://www.youtube.com/watch?v=ubK6Q53jKg8&amp;t=405s" target="_blank" rel="noopener">6:45</a>)</li><li><strong>The trap test:</strong> He marked the &quot;send to race engineer&quot; button as needing a human. In UI SDK that&#39;s done with data-agent-confirm plus an allow callback that asks the user, and you can also hide sections or redact secret fields. Bridge agents always stopped for approval, but all three browser agents just clicked send. Note that with no rules set, the bridge allows any unmarked action (<a href="https://www.youtube.com/watch?v=ubK6Q53jKg8&amp;t=360s" target="_blank" rel="noopener">6:00</a>–<a href="https://www.youtube.com/watch?v=ubK6Q53jKg8&amp;t=450s" target="_blank" rel="noopener">7:30</a>)</li></ul><div class="sh">Reception</div><ul><li><strong>Mixed reactions:</strong> The creators of React Aria and Zag.js say they&#39;ve offered reusable behaviours for years, and others note that agents&#39; real weakness is design, which unstyled parts don&#39;t fix. Solid UI is rebuilding on UI SDK, but Shadcn UI itself hasn&#39;t said whether it will switch, and the APIs are still early beta (<a href="https://www.youtube.com/watch?v=ubK6Q53jKg8&amp;t=405s" target="_blank" rel="noopener">6:45</a>–<a href="https://www.youtube.com/watch?v=ubK6Q53jKg8&amp;t=541s" target="_blank" rel="noopener">9:01</a>)</li></ul></div></article></div>',1))])}const I=h(g,[["render",f]]);export{K as __pageData,I as default};
